def _glyph(font, ch):
    g = GLYPHS[font]["g"]
    rec = g.get(ch)
    if rec is None:
        rec = g.get("?")
    raw = bytes.fromhex(rec)
    return raw[0], raw[1], raw[2], raw[3] - 128, raw[4] - 128, raw[5:]


def text_width(text, font):
    total = 0
    for ch in text:
        adv, _, _, _, _, _ = _glyph(font, ch)
        total += adv
    return total


def wrap_text(text, font, width):
    lines = []
    for para in text.split("\n"):
        words = para.split(" ")
        cur = ""
        for word in words:
            trial = word if not cur else cur + " " + word
            if text_width(trial, font) <= width or not cur:
                cur = trial
            else:
                lines.append(cur)
                cur = word
        if cur:
            lines.append(cur)
    return lines


class Canvas:
    def __init__(self):
        self.buf = bytearray(W * H * 3)
        r, g, b = PAPER
        for i in range(0, len(self.buf), 3):
            self.buf[i] = r
            self.buf[i + 1] = g
            self.buf[i + 2] = b

    def px(self, x, y, col):
        if 0 <= x < W and 0 <= y < H:
            i = (y * W + x) * 3
            self.buf[i], self.buf[i + 1], self.buf[i + 2] = col

    def fill(self, x, y, w, h, col):
        x0 = max(0, x)
        y0 = max(0, y)
        x1 = min(W, x + w)
        y1 = min(H, y + h)
        r, g, b = col
        for yy in range(y0, y1):
            base = (yy * W + x0) * 3
            for xx in range(x0, x1):
                i = base + (xx - x0) * 3
                self.buf[i] = r
                self.buf[i + 1] = g
                self.buf[i + 2] = b

    def box(self, x, y, w, h, col, t=1):
        self.fill(x, y, w, t, col)
        self.fill(x, y + h - t, w, t, col)
        self.fill(x, y, t, h, col)
        self.fill(x + w - t, y, t, h, col)

    def hline(self, x, y, w, col, t=1):
        self.fill(x, y, w, t, col)

    def vline(self, x, y, h, col, t=1):
        self.fill(x, y, t, h, col)

    def line(self, x0, y0, x1, y1, col):
        dx = abs(x1 - x0)
        dy = -abs(y1 - y0)
        sx = 1 if x0 < x1 else -1
        sy = 1 if y0 < y1 else -1
        err = dx + dy
        while True:
            self.px(x0, y0, col)
            if x0 == x1 and y0 == y1:
                return
            e2 = 2 * err
            if e2 >= dy:
                err += dy
                x0 += sx
            if e2 <= dx:
                err += dx
                y0 += sy

    def ellipse(self, cx, cy, rx, ry, col):
        for dy in range(-ry, ry + 1):
            if ry == 0:
                continue
            span = int(rx * (1.0 - (dy * dy) / float(ry * ry)) ** 0.5)
            self.fill(cx - span, cy + dy, span * 2 + 1, 1, col)

    def circle(self, cx, cy, r, col):
        self.ellipse(cx, cy, r, r, col)

    def ring(self, cx, cy, r, col, t=2):
        for dy in range(-r, r + 1):
            span = int(r * (1.0 - (dy * dy) / float(r * r)) ** 0.5) if r else 0
            inner = int((r - t) * (1.0 - (dy * dy) / float((r - t) * (r - t))) ** 0.5) if r - t > abs(dy) else 0
            self.fill(cx - span, cy + dy, span - inner, 1, col)
            self.fill(cx + inner, cy + dy, span - inner + 1, 1, col)

    def poly(self, pts, col):
        if len(pts) < 3:
            return
        ys = [p[1] for p in pts]
        for y in range(max(0, min(ys)), min(H, max(ys) + 1)):
            xs = []
            n = len(pts)
            for i in range(n):
                x0, y0 = pts[i]
                x1, y1 = pts[(i + 1) % n]
                if (y0 <= y < y1) or (y1 <= y < y0):
                    if y1 != y0:
                        xs.append(x0 + (y - y0) * (x1 - x0) / (y1 - y0))
            xs.sort()
            for i in range(0, len(xs) - 1, 2):
                self.fill(int(xs[i]), y, int(xs[i + 1]) - int(xs[i]) + 1, 1, col)

    def blit(self, x, y, w, h, cov):
        # cov holds 4-bit coverage per pixel (one linear stream, two
        # pixels per byte, high nibble first). Blend each covered pixel
        # between the ink colour and whatever background is already
        # underneath it, so text stays smooth on paper, on coloured
        # scenes and on the black top band.
        ir, ig, ib = self._ink
        for yy in range(h):
            py = y + yy
            if py < 0 or py >= H:
                continue
            for xx in range(w):
                idx = yy * w + xx
                byte = cov[idx // 2]
                a = (byte >> 4) if idx % 2 == 0 else (byte & 15)
                if a == 0:
                    continue
                px = x + xx
                if px < 0 or px >= W:
                    continue
                i = (py * W + px) * 3
                if a == 15:
                    self.buf[i] = ir
                    self.buf[i + 1] = ig
                    self.buf[i + 2] = ib
                else:
                    na = 15 - a
                    self.buf[i] = (ir * a + self.buf[i] * na) // 15
                    self.buf[i + 1] = (ig * a + self.buf[i + 1] * na) // 15
                    self.buf[i + 2] = (ib * a + self.buf[i + 2] * na) // 15

    def text(self, s, x, y, font, col, align="l", track=0):
        w = text_width(s, font) + track * max(0, len(s) - 1)
        if align == "c":
            x -= w // 2
        elif align == "r":
            x -= w
        self._ink = col
        asc = GLYPHS[font]["asc"]
        cx = x
        for ch in s:
            adv, gw, gh, x0, y0, bits = _glyph(font, ch)
            if gw and gh:
                self.blit(cx + x0, y + y0 - asc, gw, gh, bits)
            cx += adv + track
        return w

    def para(self, s, x, y, font, col, width, lh=None):
        if lh is None:
            lh = GLYPHS[font]["asc"] + GLYPHS[font]["desc"] + 2
        lines = wrap_text(s, font, width)
        for ln in lines:
            self.text(ln, x, y, font, col)
            y += lh
        return y

    def png(self):
        raw = bytearray()
        for yy in range(H):
            raw.append(0)
            raw += self.buf[yy * W * 3:(yy + 1) * W * 3]
        comp = zlib.compress(bytes(raw), 9)

        def chunk(tag, data):
            out = struct.pack(">I", len(data)) + tag + data
            out += struct.pack(">I", zlib.crc32(tag + data) & 0xFFFFFFFF)
            return out

        ihdr = struct.pack(">IIBBBBB", W, H, 8, 2, 0, 0, 0)
        return b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", ihdr) + chunk(b"IDAT", comp) + chunk(b"IEND", b"")


# ---------------------------------------------------------------- visuals

SKY = (52, 90, 140)
SAND = (214, 196, 150)


def _sky(c, x, y, w, h, sun=(240, 200, 80)):
    c.fill(x, y, w, h, SKY)
    c.fill(x, y, w, h // 3, (74, 116, 168))
    c.circle(x + w - 26, y + 20, 12, sun)


def _pitch(c, x, y, w, h, green=(34, 139, 64)):
    c.fill(x, y, w, h, green)
    c.fill(x, y, w, h // 2, (44, 152, 74))
    c.box(x + 4, y + 4, w - 8, h - 8, WHITE, 1)
    c.vline(x + w // 2, y + 4, h - 8, WHITE, 1)
    c.circle(x + w // 2, y + h // 2, 9, WHITE)
    c.ring(x + w // 2, y + h // 2, 9, green, 7)


def _ball(c, cx, cy, r=7):
    c.circle(cx, cy, r, WHITE)
    c.ring(cx, cy, r, INK, 1)
    c.circle(cx, cy, 2, INK)


def _flames(c, x, y, w, h):
    c.fill(x, y, w, h, (40, 30, 26))
    for i, fx in enumerate((0.15, 0.45, 0.75)):
        bx = x + int(w * fx)
        bh = h - 8 - i * 4
        c.poly([(bx - 12, y + h - 4), (bx, y + h - bh), (bx + 12, y + h - 4)], (230, 90, 20))
        c.poly([(bx - 6, y + h - 4), (bx, y + h - bh + 12), (bx + 6, y + h - 4)], (250, 190, 40))


def _building(c, x, y, w, h, col=(150, 148, 140)):
    c.fill(x, y, w, h, col)
    for wy in range(y + 8, y + h - 8, 12):
        for wx in range(x + 6, x + w - 8, 12):
            c.fill(wx, wy, 6, 7, (60, 58, 52))


def _smoke(c, cx, cy):
    for dx, dy, r in ((-14, 0, 8), (0, -8, 10), (14, -2, 8), (4, -16, 7)):
        c.circle(cx + dx, cy + dy, r, (120, 118, 112))


def visual(c, kind, x, y, w, h):
    if kind == "cop":
        _sky(c, x, y, w, h)
        c.circle(x + w // 2, y + h // 2 + 6, 26, (46, 140, 90))
        c.circle(x + w // 2 - 8, y + h // 2, 8, (120, 200, 150))
        c.circle(x + w // 2 + 10, y + h // 2 + 12, 6, (120, 200, 150))
        c.line(x + w // 2 - 20, y + h // 2 - 14, x + w // 2 - 6, y + h // 2 + 2, WHITE)
        c.line(x + w // 2 - 6, y + h // 2 + 2, x + w // 2 + 6, y + h // 2 - 8, WHITE)
        c.line(x + w // 2 + 6, y + h // 2 - 8, x + w // 2 + 20, y + h // 2 + 6, WHITE)
        c.fill(x, y + h - 8, w, 8, (30, 70, 50))
    elif kind == "kyiv":
        _sky(c, x, y, w, h, sun=(220, 210, 190))
        _building(c, x + 14, y + 22, 44, h - 22)
        _building(c, x + 62, y + 34, 36, h - 34, (120, 118, 110))
        c.poly([(x + 58, y + 22), (x + 58, y + h), (x + 98, y + h)], (70, 66, 60))
        _smoke(c, x + 76, y + 26)
        c.poly([(x + 104, y + h - 4), (x + 116, y + h - 26), (x + 128, y + h - 4)], (240, 120, 30))
    elif kind == "bahrain":
        c.fill(x, y, w, h, (58, 52, 48))
        c.fill(x + 10, y + h - 30, 34, 30, (120, 118, 112))
        c.fill(x + 48, y + h - 42, 30, 42, (140, 138, 130))
        c.fill(x + 82, y + h - 24, 40, 24, (100, 98, 92))
        c.fill(x + 52, y + h - 52, 4, 10, (90, 88, 84))
        _smoke(c, x + 64, y + 26)
        c.poly([(x + 96, y + h - 4), (x + 108, y + h - 30), (x + 120, y + h - 4)], (250, 150, 30))
    elif kind == "f1":
        c.fill(x, y, w, h, (18, 18, 30))
        c.fill(x, y + h - 18, w, 4, (200, 200, 200))
        for i in range(0, w, 16):
            c.fill(x + i, y + h - 18, 8, 4, BLACK)
        c.fill(x + 18, y + h // 2 - 6, 52, 12, (200, 20, 30))
        c.fill(x + 66, y + h // 2 - 12, 18, 8, (200, 20, 30))
        c.circle(x + 30, y + h // 2 + 8, 7, BLACK)
        c.circle(x + 62, y + h // 2 + 8, 7, BLACK)
        c.circle(x + 30, y + h // 2 + 8, 3, (180, 180, 180))
        c.circle(x + 62, y + h // 2 + 8, 3, (180, 180, 180))
        c.fill(x + 96, y + 10, 26, 10, WHITE)
        c.fill(x + 102, y + 10, 5, 10, BLACK)
        c.fill(x + 112, y + 10, 5, 10, BLACK)
    elif kind == "market":
        c.fill(x, y, w, h, WHITE)
        for gy in range(y + 8, y + h - 4, 12):
            c.hline(x + 4, gy, w - 8, (220, 220, 220))
        pts = [(x + 6, y + 16), (x + w // 3, y + 22), (x + w // 2, y + 18),
               (x + 2 * w // 3, y + 34), (x + w - 8, y + h - 12)]
        for i in range(len(pts) - 1):
            c.line(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1], RED)
            c.line(pts[i][0], pts[i][1] + 1, pts[i + 1][0], pts[i + 1][1] + 1, RED)
        c.poly([(x + w - 16, y + h - 22), (x + w - 6, y + h - 22), (x + w - 11, y + h - 10)], RED)
    elif kind == "gaza":
        c.fill(x, y, w, h, SAND)
        c.fill(x, y + h - 26, w, 26, (190, 170, 120))
        c.fill(x + 16, y + h // 2 - 8, 56, 22, (230, 228, 220))
        c.fill(x + 72, y + h // 2 - 2, 22, 16, (200, 80, 40))
        c.circle(x + 30, y + h - 8, 7, BLACK)
        c.circle(x + 62, y + h - 8, 7, BLACK)
        c.circle(x + 84, y + h - 8, 7, BLACK)
        _smoke(c, x + 104, y + 22)
    elif kind == "boat":
        c.fill(x, y, w, h, (40, 110, 170))
        c.fill(x, y, w, 12, (120, 190, 230))
        for wy in (22, 34, 46):
            for wx in range(x + 4, x + w - 4, 18):
                c.line(wx, y + wy, wx + 8, y + wy, WHITE)
        c.poly([(x + 20, y + h // 2), (x + w - 20, y + h // 2), (x + w - 34, y + h - 12), (x + 34, y + h - 12)], (120, 70, 30))
        for bx in (44, 62, 80, 98):
            c.circle(x + bx, y + h // 2 - 6, 5, (240, 200, 160))
    elif kind == "foot":
        _pitch(c, x, y, w, h)
        _ball(c, x + w // 2 + 18, y + h // 2 - 6, 8)
        c.fill(x + 8, y + h - 16, 26, 12, (200, 20, 30))
        c.fill(x + w - 34, y + 8, 26, 12, WHITE)
    elif kind == "drone":
        _sky(c, x, y, w, h)
        c.fill(x, y + h - 22, w, 22, (90, 110, 60))
        c.fill(x + 20, y + h - 34, 30, 12, (70, 74, 66))
        c.circle(x + 35, y + h - 36, 5, (50, 54, 48))
        cx, cy = x + w // 2 + 14, y + 26
        c.fill(cx - 12, cy - 3, 24, 6, INK)
        c.fill(cx - 3, cy - 12, 6, 24, INK)
        c.hline(cx - 18, cy - 12, 36, INK, 2)
        c.hline(cx - 18, cy + 10, 36, INK, 2)
        c.circle(cx, cy, 4, RED)
    elif kind == "fire":
        _flames(c, x, y, w, h)
        c.fill(x + 10, y + h - 26, 26, 26, (60, 58, 54))
        c.fill(x + w - 40, y + h - 20, 30, 20, (70, 68, 62))
    elif kind == "hull":
        _pitch(c, x, y, w, h, (30, 120, 70))
        _ball(c, x + w // 2 - 10, y + h // 2 + 4, 8)
        c.fill(x + w - 40, y + 8, 30, 12, (240, 200, 40))
    elif kind == "trump":
        c.fill(x, y, w, h, (30, 60, 110))
        c.fill(x + 18, y + 8, w - 36, h - 16, WHITE)
        c.fill(x + 26, y + 16, w - 52, 4, INK)
        for i, ly in enumerate((28, 38, 48)):
            c.fill(x + 26, y + ly, w - 52 - i * 12, 2, (150, 150, 150))
        c.circle(x + w - 34, y + h - 22, 10, RED)
        c.circle(x + w - 34, y + h - 22, 6, (255, 220, 220))
    elif kind == "france":
        _sky(c, x, y, w, h, sun=(240, 220, 160))
        c.fill(x + 8, y + 14, w - 16, 16, (200, 30, 40))
        c.fill(x + 8, y + 14, w - 16, 5, WHITE)
        for i, hx in enumerate((20, 44, 68, 92, 116)):
            c.circle(x + hx, y + h - 26, 8, (240, 200, 160))
            c.fill(x + hx - 9, y + h - 18, 18, 18, (60 + i * 20, 80, 140))
    elif kind == "tennis":
        c.fill(x, y, w, h, (40, 90, 170))
        c.fill(x + 8, y + 8, w - 16, h - 16, (60, 140, 90))
        c.vline(x + w // 2, y + 8, h - 16, WHITE, 2)
        c.hline(x + 8, y + h // 2, w - 16, WHITE, 2)
        c.circle(x + w // 2 + 22, y + h // 2 - 12, 6, (220, 240, 60))
    elif kind == "nba":
        c.fill(x, y, w, h, (200, 110, 40))
        c.fill(x + 8, y + 8, w - 16, h - 16, (220, 140, 70))
        c.circle(x + w // 2, y + h // 2, 14, WHITE)
        c.ring(x + w // 2, y + h // 2, 14, (200, 110, 40), 11)
        c.circle(x + w - 22, y + 18, 7, (230, 120, 40))
        c.ring(x + w - 22, y + 18, 7, BLACK, 1)
    elif kind == "rugby":
        _pitch(c, x, y, w, h, (28, 110, 60))
        c.ellipse(x + w // 2, y + h // 2, 14, 9, (240, 230, 210))
        c.vline(x + w // 2, y + h // 2 - 9, 18, RED, 2)
    elif kind == "plane":
        _sky(c, x, y, w, h)
        c.fill(x + 20, y + h // 2 - 4, 70, 8, WHITE)
        c.poly([(x + 86, y + h // 2 - 4), (x + 108, y + h // 2), (x + 86, y + h // 2 + 4)], WHITE)
        c.poly([(x + 44, y + h // 2 - 4), (x + 56, y + h // 2 - 16), (x + 62, y + h // 2 - 4)], WHITE)
        c.fill(x + 8, y + h - 20, w - 16, 4, (90, 90, 90))
    else:
        c.fill(x, y, w, h, LIGHT)
        c.circle(x + w // 2, y + h // 2, 16, GOLD)
        c.text("?", x + w // 2, y + h // 2 + 5, "P19", INK, align="c")


