# ---------------------------------------------------------------- layout

M = 14
CW = W - 2 * M


def draw_page(c):
    # Top band.
    c.fill(0, 0, W, 24, BLACK)
    c.text("THE WORLD IN ONE DAY", 22, 17, "S10", WHITE)
    c.text("40 STORIES - 7 REGIONS - EVERY ONE DATED SUNDAY 22 NOVEMBER 2026",
           W - 22, 17, "S10", WHITE, align="r")
    # Masthead.
    c.text("SUNDAY 22 NOVEMBER 2026", W // 2, 74, "P52", INK, align="c", track=1)
    c.text("COP31 COLLAPSES - KYIV FLAT HIT - BAHRAIN ACCUSES IRAN",
           W // 2, 96, "P13", INK, align="c")
    c.fill(M, 102, CW, 3, GOLD)
    # UTC strip.
    c.fill(M, 108, 118, 34, BLACK)
    c.text("THE DAY IN UTC", M + 59, 130, "S10", WHITE, align="c")
    c.hline(150, 125, W - M - 150, INK, 2)
    for i, (t, label) in enumerate(TIMELINE):
        dx = 172 + i * 156
        c.text(t, dx, 120, "S10", INK, align="c")
        c.circle(dx, 125, 4, RED)
        c.circle(dx, 125, 2, WHITE)
        c.text(label, dx, 142, "S10", INK, align="c")
    # Stat boxes.
    bw = (CW - 5 * 5) // 6
    for i, (num, label) in enumerate(STATS):
        bx = M + i * (bw + 5)
        c.fill(bx, 150, bw, 38, LIGHT)
        c.box(bx, 150, bw, 38, (200, 194, 180), 1)
        c.text(num, bx + bw // 2, 172, "P19", INK, align="c")
        c.text(label, bx + bw // 2, 185, "S10", GREY, align="c")
    # Region bar.
    widths = [300, 174, 124, 148, 98, 76, 76]
    rx = M
    for (name, count), rw in zip(REGION_BAR, widths):
        col = REGION_COLOURS[name]
        c.fill(rx, 194, rw, 22, col)
        c.text("%s %d" % (name, count), rx + rw // 2, 209, "S10", WHITE, align="c")
        rx += rw
    # Top-3 highlight cards.
    ty = 222
    th = 198
    tw = 324
    for i, (num, kicker, region, kind, head, body) in enumerate(HIGHLIGHTS[:3]):
        x = M + i * (tw + 12)
        c.fill(x, ty, tw, th, WHITE)
        c.box(x, ty, tw, th, (200, 194, 180), 1)
        visual(c, kind, x + 2, ty + 2, tw - 4, 88)
        c.text("%s %s" % (num, kicker), x + 6, ty + 102, "S10", RED)
        hy = ty + 122
        for ln in wrap_text(head, "P18", tw - 12)[:2]:
            c.text(ln, x + 6, hy, "P18", INK)
            hy += 21
        by = hy + 2
        for ln in wrap_text(body, "S11", tw - 12)[:4]:
            c.text(ln, x + 6, by, "S11", INK)
            by += 13
    # Small highlight cards, 2 rows of 5.
    sw = (CW - 4 * 8) // 5
    sh = 146
    for r in range(2):
        for k in range(5):
            item = HIGHLIGHTS[3 + r * 5 + k]
            num, kicker, region, kind, head, body = item
            x = M + k * (sw + 8)
            y = 426 + r * (sh + 6)
            c.fill(x, y, sw, sh, WHITE)
            c.box(x, y, sw, sh, (200, 194, 180), 1)
            visual(c, kind, x + 2, y + 2, sw - 4, 54)
            c.text("%s %s" % (num, kicker), x + 5, y + 66, "S10", RED)
            hy = y + 81
            for ln in wrap_text(head, "P13", sw - 10)[:2]:
                c.text(ln, x + 5, hy, "P13", INK)
                hy += 13
            by = hy + 1
            for ln in wrap_text(body, "S10R", sw - 10)[:4]:
                c.text(ln, x + 5, by, "S10R", INK)
                by += 11
    # Section headers.
    c.text("WHERE IT HAPPENED", M, 736, "S10", RED)
    c.text("ALSO ON SUNDAY 22 NOVEMBER 2026 - 27 MORE", 500, 736, "S10", RED)
    c.fill(M, 740, CW, 2, GOLD)
    # World map, bottom left.
    mx, my, mw, mh = M, 744, 472, 172
    c.fill(mx, my, mw, mh, SEA)
    c.box(mx, my, mw, mh, (160, 150, 130), 1)
    for (ex, ey, erx, ery) in (
            (90, 58, 62, 32), (168, 26, 16, 10), (130, 126, 26, 32),
            (250, 104, 40, 40), (252, 46, 30, 19), (340, 54, 78, 34),
            (380, 108, 26, 10), (410, 136, 26, 15)):
        c.ellipse(mx + ex, my + ey, erx, ery, LAND)
    nudge = {"2": (10, 4), "5": (-8, -8), "8": (-10, -6), "9": (-14, -8),
             "11": (18, -10), "12": (14, 6), "13": (8, 8)}
    for (num, lat, lon, region) in PINS:
        px = mx + int((lon + 170) / 360.0 * mw)
        py = my + int((78 - lat) / 136.0 * mh)
        dx, dy = nudge.get(num, (0, 0))
        px += dx
        py += dy
        c.circle(px, py, 8, REGION_COLOURS[region])
        c.ring(px, py, 8, WHITE, 1)
        c.text(num, px, py + 3, "S10", WHITE, align="c")
    c.text("PINS: HIGHLIGHTS 1-13. COLOUR = REGION.", mx + 8, my + mh - 6, "S10", INK)
    # Also list, bottom right, two columns.
    col_w = 248
    for idx, item in enumerate(ALSO):
        col = 0 if idx < 14 else 1
        row = idx if idx < 14 else idx - 14
        lx = 500 + col * (col_w + 8)
        ly = 760 + row * 12
        c.text("%d %s" % (14 + idx, item), lx, ly, "S10", INK)
    # Date check box. Sized from the wrapped text, not guessed: the
    # title baseline sits at dy+13, the paragraph's first baseline at
    # dy+27 with lh 13, descenders run 3 px below the last baseline,
    # and 8 px of padding is left inside the bottom border. The footer
    # then starts 15 px below the box bottom (8 px gap + 7 px cap
    # height), so no glyph touches a border or the page edge.
    dc_lines = wrap_text(DATE_CHECK, "S11", CW - 16)
    dy = 920
    dc_h = 27 + 13 * (len(dc_lines) - 1) + 3 + 8
    c.fill(M, dy, CW, dc_h, WHITE)
    c.box(M, dy, CW, dc_h, RED, 2)
    c.text("DATE CHECK - READ BEFORE YOU QUOTE", M + 8, dy + 13, "S10", RED)
    c.para(DATE_CHECK, M + 8, dy + 27, "S11", INK, CW - 16, 13)
    # Footer.
    c.para(FOOTER, M, dy + dc_h + 15, "S10", INK, CW, 12)


def main():
    out = sys.argv[1] if len(sys.argv) > 1 else "/output/entry.png"
    d = os.path.dirname(out)
    if d:
        os.makedirs(d, exist_ok=True)
    c = Canvas()
    draw_page(c)
    with open(out, "wb") as fh:
        fh.write(c.png())
    sys.stdout.write("wrote %s (%d bytes)\n" % (out, os.path.getsize(out)))


if __name__ == "__main__":
    main()
